import React, { useState, useRef, useCallback, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const [stream, setStream] = useState(null);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState("");
  const [autoMode, setAutoMode] = useState(false);

  // ================= DÉMARRER LA CAMÉRA =================
  useEffect(() => {
    let mediaStream = null;

    const startCamera = async () => {
      try {
        mediaStream = await navigator.mediaDevices.getUserMedia({
          video: { 
            facingMode: "user", 
            width: 1280, 
            height: 720 
          }
        });
        setStream(mediaStream);
        if (videoRef.current) {
          videoRef.current.srcObject = mediaStream;
        }
        setStatus("");
      } catch (err) {
        setStatus("❌ Impossible d'accéder à la caméra. Vérifiez les permissions.");
      }
    };

    startCamera();

    // Nettoyage automatique
    return () => {
      if (mediaStream) {
        mediaStream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  // ================= ARRÊTER LA CAMÉRA =================
  const stopCamera = useCallback(() => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setAutoMode(false);
    setStatus("📴 Caméra arrêtée");
  }, [stream]);

  // ================= CAPTURE & RECONNAISSANCE =================
  const handleCapture = useCallback(async () => {
    if (!videoRef.current) {
      setStatus("❌ Caméra non disponible");
      return;
    }

    setLoading(true);
    setStatus("⏳ Capture et analyse en cours...");

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageSrc = canvas.toDataURL('image/jpeg', 0.92);

      console.log("📸 Image capturée - Longueur base64:", imageSrc.length);

      const response = await attendanceAPI.recognize(imageSrc);
      const data = response?.data || response || {};

      console.log("✅ Réponse du serveur:", data);

      const name = String(data.student || data.student_name || data.name || "Inconnu");
      const confidence = (Number(data.confidence || 0) * 100).toFixed(1);

      if (data.success || name !== "Inconnu") {
        setStatus(`✅ ${name} - Confiance : ${confidence}%`);
      } else {
        setStatus(`⚠️ ${String(data.message || data.error || "Visage non reconnu")}`);
      }
    } catch (err) {
      console.error("❌ Erreur complète:", err);
      const errorMsg = err.response?.data?.error 
                    || err.response?.data?.message 
                    || err.message 
                    || "Erreur serveur (400)";
      setStatus(`❌ ${String(errorMsg)}`);
    } finally {
      setLoading(false);
    }
  }, []);

  // ================= AUTO SCAN =================
  useEffect(() => {
    let interval = null;
    if (autoMode && !loading) {
      interval = setInterval(handleCapture, 5000);
    }
    return () => clearInterval(interval);
  }, [autoMode, loading, handleCapture]);

  return (
    <div style={{ padding: '40px', maxWidth: '800px', margin: '0 auto', textAlign: 'center' }}>
      <h1 style={{ marginBottom: '30px' }}>📷 Reconnaissance Faciale</h1>

      <div style={{ 
        borderRadius: '16px', 
        overflow: 'hidden', 
        background: '#000', 
        marginBottom: '30px',
        boxShadow: '0 10px 40px rgba(0,0,0,0.3)',
        minHeight: '480px'
      }}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={{ width: '100%', height: 'auto', display: 'block' }}
        />
      </div>

      <div style={{ display: 'flex', gap: '15px', marginBottom: '30px' }}>
        <button 
          onClick={handleCapture}
          disabled={loading}
          style={{
            flex: 1,
            padding: '16px',
            fontSize: '17px',
            background: loading ? '#6b7280' : '#4F46E5',
            color: 'white',
            border: 'none',
            borderRadius: '10px',
            cursor: loading ? 'not-allowed' : 'pointer',
            fontWeight: '600'
          }}
        >
          {loading ? '⏳ Analyse...' : '🔍 Capturer & Analyser'}
        </button>

        <button 
          onClick={() => setAutoMode(!autoMode)}
          style={{
            flex: 1,
            padding: '16px',
            fontSize: '17px',
            background: autoMode ? '#EF4444' : '#10B981',
            color: 'white',
            border: 'none',
            borderRadius: '10px',
            cursor: 'pointer',
            fontWeight: '600'
          }}
        >
          {autoMode ? '⏹ STOP AUTO' : '🔄 AUTO SCAN'}
        </button>
      </div>

      <button 
        onClick={stopCamera}
        style={{
          padding: '14px 32px',
          background: '#EF4444',
          color: 'white',
          border: 'none',
          borderRadius: '10px',
          cursor: 'pointer',
          fontSize: '16px',
          fontWeight: '600',
          marginBottom: '20px'
        }}
      >
        🛑 Arrêter la Caméra
      </button>

      {status && (
        <div style={{
          padding: '25px',
          borderRadius: '12px',
          fontSize: '20px',
          backgroundColor: status.includes('✅') ? '#DCFCE7' : '#FEE2E2',
          color: status.includes('✅') ? '#166534' : '#991B1B',
          border: `3px solid ${status.includes('✅') ? '#86EFAC' : '#FECACA'}`
        }}>
          {status}
        </div>
      )}
    </div>
  );
};

export default CameraRecognition;
